1	import { eq, and, desc } from "drizzle-orm";
2	import { db } from "~/db";
3	import { courseReviews, users } from "~/db/schema";
4	
5	export function getReviewsForCourse(courseId: number) {
6	  return db
7	    .select({
8	      id: courseReviews.id,
9	      userId: courseReviews.userId,
10	      rating: courseReviews.rating,
11	      body: courseReviews.body,
12	      createdAt: courseReviews.createdAt,
13	      userName: users.name,
14	      userAvatarUrl: users.avatarUrl,
15	    })
16	    .from(courseReviews)
17	    .leftJoin(users, eq(courseReviews.userId, users.id))
18	    .where(eq(courseReviews.courseId, courseId))
19	    .orderBy(desc(courseReviews.createdAt))
20	    .all();
21	}
22	
23	export function getAverageRatingForCourse(courseId: number): number | null {
24	  const reviews = db
25	    .select({ rating: courseReviews.rating })
26	    .from(courseReviews)
27	    .where(eq(courseReviews.courseId, courseId))
28	    .all();
29	
30	  if (reviews.length === 0) return null;
31	  const sum = reviews.reduce((acc, r) => acc + r.rating, 0);
32	  return Math.round((sum / reviews.length) * 10) / 10;
33	}
34	
35	export function getReviewCountForCourse(courseId: number): number {
36	  return db
37	    .select({ id: courseReviews.id })
38	    .from(courseReviews)
39	    .where(eq(courseReviews.courseId, courseId))
40	    .all().length;
41	}
42	
43	export function getUserReviewForCourse(userId: number, courseId: number) {
44	  return db
45	    .select()
46	    .from(courseReviews)
47	    .where(
48	      and(
49	        eq(courseReviews.userId, userId),
50	        eq(courseReviews.courseId, courseId)
51	      )
52	    )
53	    .get();
54	}
55	
56	export function createOrUpdateReview(
57	  userId: number,
58	  courseId: number,
59	  rating: number,
60	  body: string | null
61	) {
62	  const existing = getUserReviewForCourse(userId, courseId);
63	  if (existing) {
64	    db.update(courseReviews)
65	      .set({ rating, body, updatedAt: new Date().toISOString() })
66	      .where(eq(courseReviews.id, existing.id))
67	      .run();
68	  } else {
69	    db.insert(courseReviews).values({ userId, courseId, rating, body }).run();
70	  }
71	}
72	
73	export function deleteReview(id: number, userId: number) {
74	  db.delete(courseReviews)
75	    .where(and(eq(courseReviews.id, id), eq(courseReviews.userId, userId)))
76	    .run();
77	}
