102	export async function loader({ params, request }: Route.LoaderArgs) {
103	  const slug = params.slug;
104	  const lessonId = Number(params.lessonId);
105	
106	  if (isNaN(lessonId)) {
107	    throw data("Invalid lesson ID", { status: 400 });
108	  }
109	
110	  const course = getCourseBySlug(slug);
111	  if (!course) {
112	    throw data("Course not found", { status: 404 });
113	  }
114	
115	  const courseWithDetails = getCourseWithDetails(course.id);
116	  if (!courseWithDetails) {
117	    throw data("Course not found", { status: 404 });
118	  }
119	
120	  const lesson = getLessonById(lessonId);
121	  if (!lesson) {
122	    throw data("Lesson not found", { status: 404 });
123	  }
124	
125	  const mod = getModuleById(lesson.moduleId);
126	  if (!mod) {
127	    throw data("Module not found", { status: 404 });
128	  }
129	
130	  // Verify lesson belongs to this course
131	  if (mod.courseId !== course.id) {
132	    throw data("Lesson not found in this course", { status: 404 });
133	  }
134	
135	  const currentUserId = await getCurrentUserId(request);
136	  let enrolled = false;
137	  let lessonStatus: string | null = null;
138	  let lastWatchPosition = 0;
139	  let watchProgress = 0;
140	  let lessonProgressMap: Record<number, string> = {};
141	
142	  if (currentUserId) {
143	    enrolled = isUserEnrolled(currentUserId, course.id);
144	
145	    if (enrolled) {
146	      // Mark lesson as in-progress when viewed
147	      markLessonInProgress(currentUserId, lessonId);
148	      const progress = getLessonProgress(currentUserId, lessonId);
149	      lessonStatus = progress?.status ?? null;
150	
151	      // Get progress for all lessons in course (for curriculum sidebar)
152	      const progressRecords = getLessonProgressForCourse(
153	        currentUserId,
154	        course.id
155	      );
156	      for (const record of progressRecords) {
157	        lessonProgressMap[record.lessonId] = record.status;
158	      }
159	
160	      // Get video watch state for resume and progress display
161	      if (lesson.videoUrl) {
162	        lastWatchPosition = getLastWatchPosition(currentUserId, lessonId);
163	        const videoDurationSeconds = (lesson.durationMinutes ?? 0) * 60;
164	        if (videoDurationSeconds > 0) {
165	          watchProgress = calculateWatchProgress(
166	            currentUserId,
167	            lessonId,
168	            videoDurationSeconds
169	          );
170	        }
171	      }
172	    }
173	  }
174	
175	  // PPP Access Guard
176	  let pppBlocked = false;
177	  let pppBlockedCountry: string | null = null;
178	  let pppPurchaseCountry: string | null = null;
179	
180	  if (enrolled && currentUserId) {
181	    const purchase = findPurchase(currentUserId, course.id);
182	    const currentCountry = await resolveCountry(request);
183	    const pppResult = checkPppAccess(
184	      course.price,
185	      course.pppEnabled,
186	      purchase?.country ?? null,
187	      currentCountry
188	    );
189	    pppBlocked = pppResult.blocked;
190	    pppBlockedCountry = pppResult.blockedCountry;
191	    pppPurchaseCountry = pppResult.purchaseCountry;
192	  }
193	
194	  // Render lesson content from Markdown to HTML server-side
195	  const contentHtml = lesson.content
196	    ? await renderMarkdown(lesson.content)
197	    : null;
198	
199	  // Build prev/next navigation
200	  const allLessons = flattenCourseLessons(courseWithDetails);
201	  const currentIndex = allLessons.findIndex((l) => l.id === lessonId);
202	  const prevLesson = currentIndex > 0 ? allLessons[currentIndex - 1] : null;
203	  const nextLesson =
204	    currentIndex < allLessons.length - 1 ? allLessons[currentIndex + 1] : null;
205	
206	  // Check for quiz attached to this lesson
207	  const quizRecord = getQuizByLessonId(lessonId);
208	  let quiz: {
209	    id: number;
210	    title: string;
211	    passingScore: number;
212	    questions: Array<{
213	      id: number;
214	      questionText: string;
215	      questionType: string;
216	      position: number;
217	      options: Array<{ id: number; optionText: string }>;
218	    }>;
219	  } | null = null;
220	  let bestAttempt: { score: number; passed: boolean } | null = null;
221	
222	  if (quizRecord) {
223	    const quizData = getQuizWithQuestions(quizRecord.id);
224	    if (quizData) {
225	      // Strip isCorrect from options so answers aren't leaked to the client
226	      quiz = {
227	        id: quizData.id,
228	        title: quizData.title,
229	        passingScore: quizData.passingScore,
230	        questions: quizData.questions.map((q) => ({
231	          id: q.id,
232	          questionText: q.questionText,
233	          questionType: q.questionType,
234	          position: q.position,
235	          options: q.options.map((o) => ({
236	            id: o.id,
237	            optionText: o.optionText,
238	          })),
239	        })),
240	      };
241	    }
242	
243	    if (currentUserId) {
244	      const best = getBestAttempt(currentUserId, quizRecord.id);
245	      if (best) {
246	        bestAttempt = { score: best.score, passed: best.passed };
247	      }
248	    }
249	  }
250	
251	  return {
252	    course: {
253	      id: courseWithDetails.id,
254	      title: courseWithDetails.title,
255	      slug: courseWithDetails.slug,
256	    },
257	    curriculum: courseWithDetails.modules.map((m) => ({
258	      id: m.id,
259	      title: m.title,
260	      lessons: m.lessons.map((l) => ({
261	        id: l.id,
262	        title: l.title,
263	      })),
264	    })),
265	    module: {
266	      id: mod.id,
267	      title: mod.title,
268	    },
269	    lesson,
270	    contentHtml,
271	    lessonStatus,
272	    enrolled,
273	    currentUserId,
274	    prevLesson,
275	    nextLesson,
276	    quiz,
277	    bestAttempt,
278	    lastWatchPosition,
279	    watchProgress,
280	    lessonProgressMap,
281	    pppBlocked,
282	    pppBlockedCountry,
283	    pppPurchaseCountry,
284	  };
285	}
