287	export async function action({ params, request }: Route.ActionArgs) {
288	  const { slug, lessonId } = parseParams(params, lessonParamsSchema);
289	
290	  const course = getCourseBySlug(slug);
291	  if (!course) {
292	    throw data("Course not found", { status: 404 });
293	  }
294	
295	  const currentUserId = await getCurrentUserId(request);
296	  if (!currentUserId) {
297	    throw data("You must be logged in", { status: 401 });
298	  }
299	
300	  const formData = await request.formData();
301	  const intent = formData.get("intent");
302	
303	  if (intent === "mark-complete") {
304	    markLessonComplete(currentUserId, lessonId);
305	    return { success: true };
306	  }
307	
308	  if (intent === "submit-quiz") {
309	    const quizId = Number(formData.get("quizId"));
310	    if (isNaN(quizId)) {
311	      throw data("Invalid quiz ID", { status: 400 });
312	    }
313	
314	    // Collect answers: form fields named "question-{questionId}" with value = optionId
315	    const selectedAnswers: Record<number, number> = {};
316	    for (const [key, value] of formData.entries()) {
317	      if (key.startsWith("question-")) {
318	        const questionId = Number(key.replace("question-", ""));
319	        const optionId = Number(value);
320	        if (!isNaN(questionId) && !isNaN(optionId)) {
321	          selectedAnswers[questionId] = optionId;
322	        }
323	      }
324	    }
325	
326	    const result = computeResult(currentUserId, quizId, selectedAnswers);
327	    if (!result) {
328	      throw data("Failed to score quiz", { status: 500 });
329	    }
330	
331	    return { quizResult: result };
332	  }
333	
334	  throw data("Invalid action", { status: 400 });
335	}
