337	const AUTOPLAY_KEY = "cadence-autoplay";
338	
339	function useAutoplay() {
340	  const [enabled, setEnabled] = useState(false);
341	
342	  useEffect(() => {
343	    try {
344	      setEnabled(localStorage.getItem(AUTOPLAY_KEY) === "true");
345	    } catch {
346	      /* silently fail */
347	    }
348	  }, []);
349	
350	  const toggle = useCallback(() => {
351	    setEnabled((prev) => {
352	      const next = !prev;
353	      try {
354	        localStorage.setItem(AUTOPLAY_KEY, String(next));
355	      } catch {
356	        /* silently fail */
357	      }
358	      return next;
359	    });
360	  }, []);
361	
362	  return [enabled, toggle] as const;
363	}
