365	export default function LessonViewer({ loaderData }: Route.ComponentProps) {
366	  const {
367	    course,
368	    curriculum,
369	    module: mod,
370	    lesson,
371	    contentHtml,
372	    lessonStatus,
373	    enrolled,
374	    currentUserId,
375	    prevLesson,
376	    nextLesson,
377	    quiz,
378	    bestAttempt,
379	    lastWatchPosition,
380	    watchProgress,
381	    lessonProgressMap,
382	    pppBlocked,
383	    pppBlockedCountry,
384	    pppPurchaseCountry,
385	  } = loaderData;
386	  const [autoplay, toggleAutoplay] = useAutoplay();
387	  const fetcher = useFetcher({ key: `mark-complete-${lesson.id}` });
388	  const quizFetcher = useFetcher({ key: `quiz-${lesson.id}` });
389	  const navigate = useNavigate();
390	
391	  const isMarking =
392	    fetcher.state !== "idle" &&
393	    fetcher.formData?.get("intent") === "mark-complete";
394	
395	  const justCompleted = fetcher.data?.success;
396	
397	  const isCompleted =
398	    lessonStatus === LessonProgressStatus.Completed || justCompleted;
399	
400	  // Navigate to next lesson after marking complete
401	  useEffect(() => {
402	    if (justCompleted && nextLesson) {
403	      navigate(`/courses/${course.slug}/lessons/${nextLesson.id}`);
404	    }
405	  }, [justCompleted, nextLesson, course.slug, navigate]);
406	
407	  const quizResult = quizFetcher.data?.quizResult ?? null;
408	  const isSubmittingQuiz = quizFetcher.state !== "idle";
409	
410	  if (pppBlocked) {
411	    const purchaseCountryName = pppPurchaseCountry
412	      ? (COUNTRIES.find((c) => c.code === pppPurchaseCountry)?.name ??
413	        pppPurchaseCountry)
414	      : "your original country";
415	    const currentCountryName = pppBlockedCountry
416	      ? (COUNTRIES.find((c) => c.code === pppBlockedCountry)?.name ??
417	        pppBlockedCountry)
418	      : "a different country";
419	
420	    return (
421	      <div className="flex min-h-[60vh] items-center justify-center p-6">
422	        <div className="max-w-md text-center">
423	          <ShieldAlert className="mx-auto mb-4 size-16 text-amber-500" />
424	          <h1 className="mb-3 text-2xl font-bold">Access Restricted</h1>
425	          <p className="mb-4 text-muted-foreground">
426	            You purchased this course with a Purchasing Power Parity discount
427	            while in <strong>{purchaseCountryName}</strong>, but you're
428	            currently accessing from <strong>{currentCountryName}</strong>.
429	          </p>
430	          <p className="mb-6 text-sm text-muted-foreground">
431	            PPP-discounted courses can only be accessed from the country where
432	            the purchase was made. This helps keep courses affordable for
433	            students in lower-income regions.
434	          </p>
435	          <div className="flex items-center justify-center gap-3">
436	            <Link to={`/courses/${course.slug}`}>
437	              <Button variant="outline">
438	                <MapPin className="mr-2 size-4" />
439	                Back to Course
440	              </Button>
441	            </Link>
442	          </div>
443	        </div>
444	      </div>
445	    );
446	  }
447	
448	  return (
449	    <div className="flex">
450	      {/* Curriculum Sidebar */}
451	      <CurriculumSidebar
452	        course={course}
453	        curriculum={curriculum}
454	        currentLessonId={lesson.id}
455	        lessonProgressMap={lessonProgressMap}
456	        enrolled={enrolled}
457	      />
458	
459	      <div className="flex-1 p-6 lg:p-8">
460	        {/* Breadcrumb */}
461	        <nav className="mb-6 text-sm text-muted-foreground">
462	          <Link to="/courses" className="hover:text-foreground">
463	            Courses
464	          </Link>
465	          <span className="mx-2">/</span>
466	          <Link
467	            to={`/courses/${course.slug}`}
468	            className="hover:text-foreground"
469	          >
470	            {course.title}
471	          </Link>
472	          <span className="mx-2">/</span>
473	          <Link
474	            to={`/courses/${course.slug}/${mod.id}`}
475	            className="hover:text-foreground"
476	          >
477	            {mod.title}
478	          </Link>
479	          <span className="mx-2">/</span>
480	          <span className="text-foreground">{lesson.title}</span>
481	        </nav>
482	
483	        <div className="mx-auto max-w-4xl">
484	          {/* Lesson Title */}
485	          <h1 className="mb-2 text-3xl font-bold">{lesson.title}</h1>
486	          <div className="mb-6 flex items-center gap-3">
487	            {lesson.durationMinutes && (
488	              <div className="flex items-center gap-1 text-sm text-muted-foreground">
489	                <Clock className="size-4" />
490	                {formatDuration(lesson.durationMinutes, true, false, false)}
491	              </div>
492	            )}
493	            {lesson.githubRepoUrl && (
494	              <a
495	                href={lesson.githubRepoUrl}
496	                target="_blank"
497	                rel="noopener noreferrer"
498	              >
499	                <Button variant="outline" size="sm">
500	                  <Github className="mr-1.5 size-4" />
501	                  Open Code
502	                </Button>
503	              </a>
504	            )}
505	          </div>
506	
507	          {/* YouTube Video */}
508	          {lesson.videoUrl && (
509	            <YouTubePlayer
510	              videoUrl={lesson.videoUrl}
511	              lessonId={lesson.id}
512	              title={lesson.title}
513	              startPosition={lastWatchPosition}
514	              durationMinutes={lesson.durationMinutes}
515	              watchProgress={watchProgress}
516	              trackingEnabled={enrolled && !!currentUserId}
517	              autoplay={autoplay}
518	              onToggleAutoplay={toggleAutoplay}
519	            />
520	          )}
521	
522	          {/* Lesson Content */}
523	          {contentHtml && (
524	            <div
525	              className="prose prose-neutral dark:prose-invert mb-8 max-w-none"
526	              dangerouslySetInnerHTML={{ __html: contentHtml }}
527	            />
528	          )}
529	
530	          {!contentHtml && !lesson.videoUrl && (
531	            <Card className="mb-8">
532	              <CardContent className="py-12 text-center text-muted-foreground">
533	                No content has been added to this lesson yet.
534	              </CardContent>
535	            </Card>
536	          )}
537	
538	          {/* Quiz Section */}
539	          {quiz && enrolled && currentUserId && (
540	            <QuizSection
541	              quiz={quiz}
542	              bestAttempt={bestAttempt}
543	              quizResult={quizResult}
544	              quizFetcher={quizFetcher}
545	              isSubmitting={isSubmittingQuiz}
546	            />
547	          )}
548	
549	          {/* Mark Complete / Up Next */}
550	          {enrolled && currentUserId && (
551	            <div className="mb-8">
552	              {isCompleted ? (
553	                <div className="flex items-center gap-3">
554	                  <div className="flex items-center gap-2 text-green-600">
555	                    <CheckCircle2 className="size-5" />
556	                    <span className="font-medium">Lesson completed</span>
557	                  </div>
558	                  {nextLesson && (
559	                    <Link
560	                      to={`/courses/${course.slug}/lessons/${nextLesson.id}`}
561	                    >
562	                      <Button variant="outline" size="sm">
563	                        Up next: {nextLesson.title}
564	                        <ChevronRight className="ml-1 size-4" />
565	                      </Button>
566	                    </Link>
567	                  )}
568	                </div>
569	              ) : nextLesson ? (
570	                <fetcher.Form method="post">
571	                  <input type="hidden" name="intent" value="mark-complete" />
572	                  <Button disabled={isMarking}>
573	                    {isMarking ? (
574	                      "Completing..."
575	                    ) : (
576	                      <>
577	                        Up next: {nextLesson.title}
578	                        <ChevronRight className="ml-1 size-4" />
579	                      </>
580	                    )}
581	                  </Button>
582	                </fetcher.Form>
583	              ) : (
584	                <fetcher.Form method="post">
585	                  <input type="hidden" name="intent" value="mark-complete" />
586	                  <Button disabled={isMarking}>
587	                    <CheckCircle2 className="mr-2 size-4" />
588	                    {isMarking ? "Marking..." : "Mark as Complete"}
589	                  </Button>
590	                </fetcher.Form>
591	              )}
592	            </div>
593	          )}
