95	export async function action({ params, request }: Route.ActionArgs) {
96	  const currentUserId = await getCurrentUserId(request);
97	
98	  if (!currentUserId) {
99	    throw data("You must be logged in.", { status: 401 });
100	  }
101	
102	  const user = getUserById(currentUserId);
103	  if (!user || (user.role !== UserRole.Instructor && user.role !== UserRole.Admin)) {
104	    throw data("Only instructors and admins can edit lessons.", { status: 403 });
105	  }
106	
107	  const { courseId, lessonId } = parseParams(params, instructorLessonParamsSchema);
108	
109	  const course = getCourseById(courseId);
110	  if (!course) {
111	    throw data("Course not found.", { status: 404 });
112	  }
113	
114	  if (course.instructorId !== currentUserId && user.role !== UserRole.Admin) {
115	    throw data("You can only edit your own courses.", { status: 403 });
116	  }
117	
118	  const lesson = getLessonById(lessonId);
119	  if (!lesson) {
120	    throw data("Lesson not found.", { status: 404 });
121	  }
122	
123	  const mod = getModuleById(lesson.moduleId);
124	  if (!mod || mod.courseId !== courseId) {
125	    throw data("Lesson not found in this course.", { status: 404 });
126	  }
127	
128	  const formData = await request.formData();
129	  const parsed = parseFormData(formData, updateLessonSchema);
130	
131	  if (!parsed.success) {
132	    return data({ error: Object.values(parsed.errors)[0] ?? "Invalid input." }, { status: 400 });
133	  }
134	
135	  if (parsed.data.intent === "update-lesson") {
136	    const { content, videoUrl, durationMinutes: durationStr, githubRepoUrl } = parsed.data;
137	    const durationMinutes = durationStr ? parseInt(durationStr, 10) : null;
138	
139	    if (durationMinutes !== null && (isNaN(durationMinutes) || durationMinutes < 0)) {
140	      return data({ error: "Duration must be a positive number." }, { status: 400 });
141	    }
142	
143	    updateLesson(lessonId, null, content ?? null, videoUrl || null, durationMinutes, githubRepoUrl || null);
144	    return { success: true };
145	  }
146	
147	  throw data("Invalid action.", { status: 400 });
148	}
