399	export function ErrorBoundary({ error }: Route.ErrorBoundaryProps) {
400	  let title = "Something went wrong";
401	  let message = "An unexpected error occurred while loading the lesson editor.";
402	
403	  if (isRouteErrorResponse(error)) {
404	    if (error.status === 404) {
405	      title = "Lesson not found";
406	      message = "The lesson you're looking for doesn't exist or may have been removed.";
407	    } else if (error.status === 401) {
408	      title = "Sign in required";
409	      message = typeof error.data === "string" ? error.data : "Please select a user from the DevUI panel.";
410	    } else if (error.status === 403) {
411	      title = "Access denied";
412	      message = typeof error.data === "string" ? error.data : "You don't have permission to edit this lesson.";
413	    } else {
414	      title = `Error ${error.status}`;
415	      message = typeof error.data === "string" ? error.data : error.statusText;
416	    }
417	  }
418	
419	  return (
420	    <div className="flex min-h-[50vh] items-center justify-center p-6">
421	      <div className="text-center">
422	        <AlertTriangle className="mx-auto mb-4 size-12 text-muted-foreground" />
423	        <h1 className="mb-2 text-2xl font-bold">{title}</h1>
424	        <p className="mb-6 text-muted-foreground">{message}</p>
425	        <div className="flex items-center justify-center gap-3">
