4	type ParseSuccess<T> = { success: true; data: T };
5	type ParseFailure = {
6	  success: false;
7	  errors: Record<string, string>;
8	};
9	type ParseResult<T> = ParseSuccess<T> | ParseFailure;
10	
11	/**
12	 * Converts FormData to a plain object, validates with a Zod schema,
13	 * and returns either the parsed data or a field-error map (first error per field).
14	 */
15	export function parseFormData<T extends z.ZodType>(
16	  formData: FormData,
17	  schema: T
18	): ParseResult<z.infer<T>> {
19	  const raw = Object.fromEntries(formData);
20	  const result = schema.safeParse(raw);
21	
22	  if (result.success) {
23	    return { success: true, data: result.data };
24	  }
25	
26	  const fieldErrors = result.error.flatten().fieldErrors;
27	  const errors: Record<string, string> = {};
28	  for (const [key, messages] of Object.entries(fieldErrors)) {
29	    if (messages && messages.length > 0) {
30	      errors[key] = messages[0];
31	    }
32	  }
33	
34	  return { success: false, errors };
35	}
36	
37	/**
38	 * Validates route params with a Zod schema.
39	 * Throws a 400 response on failure (params are never user-correctable form errors).
40	 */
41	export function parseParams<T extends z.ZodType>(
42	  params: Record<string, string | undefined>,
43	  schema: T
44	): z.infer<T> {
45	  const result = schema.safeParse(params);
46	
47	  if (result.success) {
48	    return result.data;
49	  }
50	
51	  throw data("Invalid parameters", { status: 400 });
52	}
53	
54	/**
55	 * Parses a JSON request body with a Zod schema.
56	 * Returns either the parsed data or a field-error map (first error per field).
57	 */
58	export async function parseJsonBody<T extends z.ZodType>(
59	  request: Request,
60	  schema: T
61	): Promise<ParseResult<z.infer<T>>> {
62	  const raw = await request.json();
63	  const result = schema.safeParse(raw);
64	
65	  if (result.success) {
66	    return { success: true, data: result.data };
67	  }
68	
69	  const fieldErrors = result.error.flatten().fieldErrors;
70	  const errors: Record<string, string> = {};
71	  for (const [key, messages] of Object.entries(fieldErrors)) {
72	    if (messages && messages.length > 0) {
73	      errors[key] = messages[0];
74	    }
75	  }
76	
77	  return { success: false, errors };
78	}
